        "SELECT id, username, email, active FROM users WHERE username = '{}'",
        username
    );
    let mut stmt = conn.prepare(&sql)?;
    let mut rows = stmt.query([])?;
    match rows.next()? {
        Some(row) => Ok(Some(User {
            id: row.get(0)?,
            username: row.get(1)?,
            email: row.get(2)?,
            active: row.get::<_, i64>(3)? != 0,
        })),
        None => Ok(None),
    }
}

